import { EventhubSdkConfigService } from '@/config/eventhub-sdk/eventhub-sdk-config.service';
import { CombinedDtoWithIndex } from '@/dapr/dtos/combined.dto';
import { checkPayloadConsistency } from '@/helpers/validations/check-payload-consistency';
import { checkPlantConsistency } from '@/helpers/validations/check-plant-consistency';
import { OrderRouterService } from '@/order-router/order-router.service';
import { OrderStreamRouterService } from '@/order-stream-router/order-stream-router.service';

export interface MessageProcessingContext {
  method: string;
  service: string;
  plant?: number;
  object?: string;
  userId?: string;
}

@Injectable()
export class MessageProcessingPipelineService implements OnModuleInit {
  private useEventHub: boolean;

  public constructor(
    private readonly logger: AppLogger,
    private readonly orderRouterService: OrderRouterService,
    private readonly orderStreamRouterService: OrderStreamRouterService,
    private readonly plantCacheService: PlantCacheService,
    private readonly eventHubConfig: EventhubSdkConfigService,
  ) {}

  public async onModuleInit(): Promise<void> {
    this.useEventHub = await this.eventHubConfig.useEventHubRouter();
  }

  /**
   * Process a message through the complete validation and routing pipeline
   * @param message - The message to process
   * @param context - Logging context
   * @returns Promise<boolean> - Returns true if message was processed successfully
   */
  public async processMessage(
    message: CombinedDtoWithIndex,
    context: MessageProcessingContext,
  ): Promise<boolean> {
    try {
      // Step 1: Check payload consistency
      if (!checkPayloadConsistency(this.logger, context, message)) {
        this.logger.verbose(
          'Message failed payload consistency check',
          context,
        );
        return false;
      }
      if (
        !checkPlantConsistency(this.logger, message, this.plantCacheService)
      ) {
        this.logger.verbose('Message failed plant consistency check', context);
        return false;
      }

      const order = message.S_SHOP_ORDER || message.SHOP_ORDER;
      const plant = message.SITE || message.S_SITE;

      this.logger.debug(
        `Message passed validations for order ${order}, plant ${plant}`,
        context,
      );

      // Step 3: Publish order event (Event Hub or Redis Streams based on flag)
      await (this.useEventHub
        ? this.orderRouterService.publishOrderEvent(message)
        : this.orderStreamRouterService.publishOrderEvent(message));
      this.logger.debug(
        `Message processed successfully through pipeline for order ${order}`,
        context,
      );
      return true;
    } catch (error) {
      this.logger.error(
        `Failed to process message through pipeline: ${error.message}`,
        context,
        error instanceof Error ? error : new Error(String(error)),
      );
      return false;
    }
  }
}

