import { Injectable, OnModuleInit } from '@nestjs/common';
import { DaprClient } from 'dapr-client';
import { AppLogger } from '@/common/logger/app-logger';
import { PlantsResponseDto } from '@/common/subscribe/dtos/plant.response.dto';
import { SubscribeMessageService } from '@/common/subscribe/subscribe.service';
import { IngestionPolicyConfigService } from '@/config/ingestion-policy/ingestion-policy-config.service';
import { RedisConfigService } from '@/config/redis/redis-store/redis-store.service';
import { getListPlant } from '@/helpers/caches/get-plant-list';

@Injectable()
export class PlantCacheService implements OnModuleInit {
  private plantList: Array<PlantsResponseDto> = [];

  private excludedPlants: Set<string> = new Set();

  private readonly daprClient: DaprClient;

  public constructor(
    private readonly customLogger: AppLogger,
    private readonly subscribeMessageService: SubscribeMessageService,
    private readonly redisConfigService: RedisConfigService,
    private readonly ingestionPolicyConfigService: IngestionPolicyConfigService,
  ) {
    this.daprClient = new DaprClient();
  }

  public async onModuleInit(): Promise<void> {
    await this.initializePlant();
    await this.loadExcludedPlants();
  }

  public async initializePlant(): Promise<void> {
    const context = {
      method: 'initializePlant',
      service: PlantCacheService.name,
    };
    try {
      this.plantList = await getListPlant(
        this.customLogger,
        this.daprClient,
        this.subscribeMessageService,
        this.redisConfigService.redisStore,
        this.redisConfigService.redisPlantKey,
      );
      this.customLogger.log(
        `Updated Plants List: ${JSON.stringify(this.plantList)}`,
        context,
      );
    } catch (error) {
      this.customLogger.error(
        `Failed to get plant list: ${error.message}`,
        context,
        error instanceof Error ? error : new Error(String(error)),
      );
    }
  }

  private async loadExcludedPlants(): Promise<void> {
    const context = {
      method: 'loadExcludedPlants',
      service: PlantCacheService.name,
    };
    try {
      this.excludedPlants =
        await this.ingestionPolicyConfigService.getExcludedPlants();
      this.customLogger.debug(
        `Loaded ${this.excludedPlants.size} excluded plants from configuration`,
        context,
      );
    } catch (error) {
      this.customLogger.warn(
        `Failed to load excluded plants; proceeding without exclusions: ${error instanceof Error ? error.message : String(error)}`,
        context,
      );
      this.excludedPlants = new Set();
    }
  }

  public getPlantList(): Array<PlantsResponseDto> {
    return this.plantList;
  }

  public isPlantValid(plantId: number): boolean {
    const normalized = String(plantId).trim();
    if (normalized && this.excludedPlants.has(normalized)) {
      return false;
    }
    return this.plantList.some((plant) => plant.plantId === plantId);
  }

  public getExcludedPlants(): Set<string> {
    return this.excludedPlants;
  }

  public async refreshPlantCache(): Promise<void> {
    await this.initializePlant();
    await this.loadExcludedPlants();
  }
}

