import { Subscription } from '@azure/event-hubs';
import { JobsLogContext } from '@mesx/common-lib';
import { Injectable, OnModuleInit, OnModuleDestroy } from '@nestjs/common';
import { AppLogger } from '@/common/logger/app-logger';
import { MessageProcessingPipelineService } from '@/common/message-processing/message-processing-pipeline.service';
import { EventhubSdkConfigService } from '@/config/eventhub-sdk/eventhub-sdk-config.service';
import { CombinedDtoWithIndex } from '@/dapr/dtos/combined.dto';
import {
  PartitionInfo,
  performFinalCheckpoints,
} from '@/helpers/eventhub-functions/checkpoint';
import {
  EventHubClients,
  initializeEventHub,
  cleanupEventHub,
} from '@/helpers/eventhub-functions/initialization';
import { MessageProcessor } from '@/helpers/eventhub-functions/message-processing';
import {
  createShutdownState,
  ShutdownState,
} from '@/helpers/eventhub-functions/shutdown';
import {
  subscribeToEventHub,
  unsubscribeFromEventHub,
} from '@/helpers/eventhub-functions/subscription';

@Injectable()
export class EventHubSdkShopOrderService
  implements OnModuleInit, OnModuleDestroy
{
  private static createLogContext(
    method: string,
    plant?: number,
    object?: string,
    userId?: string,
  ): JobsLogContext {
    return {
      method,
      object,
      plant,
      service: EventHubSdkShopOrderService.name,
      userId,
    };
  }

  private clients: EventHubClients | null = null;

  private subscription: Subscription | null = null;

  private partitionInfo: Map<string, PartitionInfo> | null = null;

  private readonly shutdownState: ShutdownState = createShutdownState();

  public constructor(
    private readonly configService: EventhubSdkConfigService,
    private readonly messageProcessingPipelineService: MessageProcessingPipelineService,
    private readonly logger: AppLogger,
  ) {}

  public async onModuleInit(): Promise<void> {
    await this.initialize();
  }

  public async onModuleDestroy(): Promise<void> {
    await this.cleanup();
  }

  private async initialize(): Promise<void> {
    const context = EventHubSdkShopOrderService.createLogContext('initialize');

    try {
      // Check if we should skip initialization
      const useOrderRouterActor =
        await this.configService.useOrderRouterActor();

      if (!useOrderRouterActor) {
        this.logger.warn(
          `[ShopOrder] Skipping EventHub SDK initialization - useOrderRouterActor: ${useOrderRouterActor}`,
          context,
        );
        return;
      }
      this.logger.log('Initializing  container EventHub service', context);

      // Get EventHub configuration using the helper method
      const eventHubConfig = this.configService.getShopOrderConfig();

      // Initialize EventHub clients
      this.clients = await initializeEventHub(eventHubConfig, this.logger);

      // Create message processor
      const processor = this.createMessageProcessor();

      // Configure error recovery
      const errorRecoveryConfig = {
        enabled: true,
        eventHubConfig,
      };

      // Subscribe to EventHub with enhanced features
      const subscriptionResult = subscribeToEventHub(processor, {
        checkpointConfig: {
          ...eventHubConfig,
          checkpointInterval: this.configService.shopOrdercheckpointInterval,
        },
        clients: this.clients,
        errorRecoveryConfig,
        logger: this.logger,
        processingConfig: {
          serviceName: 'EventHubShopOrderEnhancedService',
        },
        shutdownState: this.shutdownState,
        subscriptionConfig: {
          enableCheckpointing: true,
          maxBatchSize: 1,
        },
      });

      this.subscription = subscriptionResult.subscription;
      this.partitionInfo = subscriptionResult.partitionInfo;

      this.logger.log(
        'Enhanced container EventHub service initialized successfully',
        context,
      );
    } catch (error) {
      this.logger.error(
        `Failed to initialize Enhanced container EventHub service: ${error.message}`,
        context,
        error instanceof Error ? error : new Error(String(error)),
      );
      throw error;
    }
  }

  private async cleanup(): Promise<void> {
    const context = EventHubSdkShopOrderService.createLogContext('cleanup');

    try {
      this.logger.log(
        'Cleaning up Enhanced container EventHub service',
        context,
      );

      // Set shutdown state to true
      this.shutdownState.value = true;

      // Perform final checkpoints
      if (this.clients && this.partitionInfo) {
        await performFinalCheckpoints(
          this.clients.checkpointStore,
          {
            checkpointInterval: this.configService.shopOrdercheckpointInterval,
            consumerGroup: this.configService.shopOrderconsumerGroup,
            eventHubName: this.configService.eventHubShopOrderName,
            eventHubNamespace: this.configService.eventHubShopOrderNamespace,
          },
          this.partitionInfo,
          this.logger,
        );
      }

      // Unsubscribe from EventHub
      if (this.subscription) {
        await unsubscribeFromEventHub(
          this.subscription,
          'EventHubShopOrderEnhancedService',
          this.logger,
        );
        this.subscription = null;
      }

      // Clean up EventHub clients
      if (this.clients) {
        await cleanupEventHub(this.clients, this.logger);
        this.clients = null;
      }

      this.partitionInfo = null;

      this.logger.log(
        'Enhanced container EventHub service cleanup completed',
        context,
      );
    } catch (error) {
      this.logger.error(
        `Error during Enhanced container EventHub service cleanup: ${error.message}`,
        context,
        error instanceof Error ? error : new Error(String(error)),
      );
    }
  }

  /**
   * Create message processor specific to container with validation and masking
   * @returns MessageProcessor configured for container  processing
   */
  private createMessageProcessor(): MessageProcessor {
    return {
      processMessage: async (message: CombinedDtoWithIndex): Promise<void> => {
        const context = EventHubSdkShopOrderService.createLogContext(
          'processMessage Shop Order',
        );
        await this.messageProcessingPipelineService.processMessage(
          message,
          context,
        );
      },
    };
  }
}
